public class BindDialog {
    public static final String TAG = "BindDialog";
    public static final <T> Observable<T> bindDialogLoading(final Dialog dlg, final Observable<T> source) {
        final Observable<T> o = source.observeOn(AndroidSchedulers.mainThread());
        return o.lift(new Observable.Operator<T, T>() {
            @Override
            public Subscriber<? super T> call(final Subscriber<? super T> child) {
                return new Subscriber<T>() {
                    @Override
                    public void onStart() {
                        super.onStart();
                        Log.e("onStart=======","dialog show");
                        new Handler(Looper.getMainLooper()).post(new Runnable() {
                            @Override
                            public void run() {
                                dlg.show();
                                Log.e("onStart===","dialog show");
                            }
                        });
                        child.onStart();
                    }

                    @Override
                    public void onCompleted() {
                        dlg.dismiss();
                        Log.e("onCompleted===","dialog dismiss");

                        child.onCompleted();
                    }

                    @Override
                    public void onError(Throwable e) {
                        dlg.dismiss();
                        Log.e("onError===","dialog dismiss");

                        child.onError(e);
                    }

                    @Override
                    public void onNext(T t) {
                        Log.e("onNext===","dialog dismiss");
                        dlg.dismiss(); // Dismiss dialog or update it. Its depend your logic.
                        child.onNext(t);
                    }
                };
            }
        });
    }
}
